46	  private static final Map<String, String> CONFIG_RESOLVER;
47	  private static final RuntimeException CLASS_LOAD_ERROR;
48	
49	  static {
50	    // this is a bit hacky, but lots of the code depends directly on usage of
51	    // Map<String, String> (JSON serialization/GRPC code) so we cannot just
52	    // refactor all code to use a case-insensitive abstraction like PinotConfiguration
53	    // without a lot of work - additionally, the config constants are string constants
54	    // instead of enums so there's no good way to iterate over them, but they are
55	    // public API so we cannot just change them to be an enum
56	    Map<String, String> configResolver = new HashMap<>();
57	    Throwable classLoadError = null;
58	
59	    try {
60	      for (Field declaredField : QueryOptionKey.class.getDeclaredFields()) {
61	        if (declaredField.getType().equals(String.class)) {
62	          int mods = declaredField.getModifiers();
63	          if (Modifier.isStatic(mods) && Modifier.isFinal(mods)) {
64	            String config = (String) declaredField.get(null);
65	            configResolver.put(config.toLowerCase(), config);
66	          }
67	        }
68	      }
69	    } catch (IllegalAccessException e) {
70	      // prefer rethrowing this during runtime instead of a ClassNotFoundException
71	      configResolver = null;
72	      classLoadError = e;
73	    }
74	
75	    CONFIG_RESOLVER = configResolver == null ? null : ImmutableMap.copyOf(configResolver);
76	    CLASS_LOAD_ERROR = classLoadError == null ? null
77	        : new RuntimeException("Failure to build case insensitive mapping.", classLoadError);
78	  }
