133	        _internedDictionaryValues[i] = new Object[cardinality];
134	      }
135	      if (!longOverflow) {
136	        if (cardinalityProduct > Long.MAX_VALUE / cardinality) {
137	          longOverflow = true;
138	        } else {
139	          cardinalityProduct *= cardinality;
140	        }
141	      }
142	      _isSingleValueColumn[i] = columnContext.isSingleValue();
143	    }
