145	       Pair<Boolean, Long> optimizedCardinality = getOptimizedGroupByCardinality(groupByExpressionSizesFromPredicates,
146	           cardinalityMap);
147	       if (optimizedCardinality.getLeft() && optimizedCardinality.getRight() != null) {
148	         longOverflow = false;
149	         cardinalityProduct = Math.min(optimizedCardinality.getRight(), cardinalityProduct);
150	       }
151	    }
152	    // TODO: Clear the holder after processing the query instead of before
153	    if (longOverflow) {
