172	        }
173	        _rawKeyHolder = new LongMapBasedHolder(groupIdMap);
174	      } else {
175	        _globalGroupIdUpperBound = Math.min((int) cardinalityProduct, numGroupsLimit);
176	        if (cardinalityProduct > arrayBasedThreshold) {
177	          // IntMapBasedHolder
